package com.stayflow.customer.ui;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.stayflow.customer.data.*;import com.stayflow.customer.model.Models.*;import java.util.*;import retrofit2.*;import retrofit2.Response;
public class BookingsActivity extends AppCompatActivity {LinearLayout p;public void onCreate(Bundle b){super.onCreate(b);p=Ui.page(this,"My Bookings");setContentView(new ScrollView(this){{addView(p);}});load();}void load(){p.removeViews(1,Math.max(0,p.getChildCount()-1));ApiClient.create(this).myBookings().enqueue(new Callback<Resp<List<Booking>>>(){public void onResponse(Call<Resp<List<Booking>>> c,Response<Resp<List<Booking>>> r){if(r.body()==null||r.body().data==null)return;for(Booking x:r.body().data){LinearLayout card=Ui.page(BookingsActivity.this,"Booking #"+x.bookingId);Ui.text(BookingsActivity.this,card,x.checkInDate+" → "+x.checkOutDate+"\n₹"+x.totalAmount+" · "+(x.status==null?"BOOKED":x.status));if(!"CANCELLED".equals(x.status))Ui.button(BookingsActivity.this,card,"Cancel booking").setOnClickListener(v->ApiClient.create(BookingsActivity.this).cancel(x.bookingId).enqueue(new Callback<Resp<Object>>(){public void onResponse(Call<Resp<Object>> c2,Response<Resp<Object>> r2){load();}public void onFailure(Call<Resp<Object>> c2,Throwable t){Ui.toast(BookingsActivity.this,t.getMessage());}}));p.addView(card);}}public void onFailure(Call<Resp<List<Booking>>> c,Throwable t){Ui.toast(BookingsActivity.this,t.getMessage());}});}}
